def gen(rng):
    def fmt(bits):
        return str(len(bits)) + '\n' + ' '.join(map(str, bits))
    tests = [fmt([0]), fmt([1]), fmt([0] * 30), fmt([1] * 30), fmt([1] + [0] * 29), fmt([0] * 29 + [1]),
             fmt([0, 0, 0, 1]), fmt([1, 0]), fmt([0, 1]), fmt([1, 1, 0, 1, 1])]
    for n in range(2, 13):
        tests.append(fmt([rng.randint(0, 1) for _ in range(n)]))
    for _ in range(6):
        tests.append(fmt([rng.randint(0, 1) for _ in range(rng.randint(13, 30))]))
    for _ in range(3):
        tests.append(fmt([0] * rng.randint(1, 10) + [rng.randint(0, 1) for _ in range(rng.randint(1, 15))]))
    for _ in range(2):
        tests.append(fmt([1] + [rng.randint(0, 1) for _ in range(29)]))
    return tests

